insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_122'
from (values
('127.830.d.1.A',3,'A student compares job listings and notices that plants increasingly hire people who can program robots and read sensor data. This observation describes a:','["trend in manufacturing careers toward automation skills", "decline in all technical jobs", "ban on training programs", "rule that factories hire only artists"]'::jsonb,0,'Careers shift toward technology skills.','original'),
('127.830.d.1.A',4,'Which source would give the most reliable data on how many manufacturing jobs a region expects to add over the next decade?','["a classmate''s guess", "a labor market projection report from a state workforce agency", "a product advertisement", "an old yearbook"]'::jsonb,1,'Use labor market data.','original'),
('127.830.d.1.B',3,'A line worker lifts 40-pound cartons from the floor all shift and develops back pain. Adjusting the work height with a lift table addresses which kind of issue?','["a pricing issue", "a payroll issue", "an ergonomic issue", "a marketing issue"]'::jsonb,2,'Ergonomics fits work to the body.','original'),
('127.830.d.1.B',4,'Solvent vapors in a poorly ventilated assembly bay raise a worry about breathing hazards. This is mainly a:','["color-matching concern", "scheduling concern only", "packaging concern", "health and environmental concern needing ventilation or substitution"]'::jsonb,3,'Ventilation controls vapor exposure.','original'),
('127.830.d.2.A',3,'A small piston pushes on enclosed oil, and the pressure is felt equally throughout the fluid and moves a much larger piston. This behavior is explained by:','["Pascal''s Law", "Murphy''s Law", "Newton''s cradle", "Ohm''s Law"]'::jsonb,0,'Pressure transmits equally in an enclosed fluid.','original'),
('127.830.d.2.A',4,'A 2 square inch piston is pushed with 100 pounds. The pressure created in the sealed fluid is:','["200 psi", "50 psi", "98 psi", "102 psi"]'::jsonb,1,'100 ÷ 2 = 50 psi.','original'),
('127.830.d.2.B',3,'In a hydraulic press, the component that turns fluid pressure into the straight-line push on the ram is the:','["filter element", "pressure gauge", "cylinder actuator", "reservoir cap"]'::jsonb,2,'Actuators convert fluid power to motion.','original'),
('127.830.d.2.B',4,'Which choice lists only actuators?','["a reservoir and a filter", "a strainer and a tank", "a gauge and a hose", "a hydraulic cylinder and a hydraulic motor"]'::jsonb,3,'Cylinders and motors do work.','original'),
('127.830.d.2.C',3,'A technician needs a part that opens and closes passages to steer oil toward either end of a cylinder. She chooses a:','["directional control valve", "sight glass", "breather cap", "suction strainer"]'::jsonb,0,'Directional valves route flow.','original'),
('127.830.d.2.C',4,'A valve that limits the highest pressure in a hydraulic system by opening to the tank is a:','["check valve", "relief valve", "needle gauge", "flow meter"]'::jsonb,1,'Relief valves cap pressure.','original'),
('127.830.d.2.D',3,'If a cylinder''s piston area is doubled and the pressure stays the same, the force it can push with:','["stays the same", "drops to zero", "doubles", "halves"]'::jsonb,2,'Force = pressure × area.','original'),
('127.830.d.2.D',4,'A cylinder needs more oil to travel its full stroke when the bore is larger because the cylinder volume:','["depends only on paint color", "decreases as bore grows", "is unrelated to size", "increases with piston area times stroke length"]'::jsonb,3,'Volume = area × stroke.','original'),
('127.830.d.2.E',3,'A sealed tank of compressed air is left in a hot sun and its pressure climbs as the temperature rises at constant volume. This follows:','["Gay-Lussac''s Law", "Ohm''s Law", "Pascal''s cradle", "Boyle''s Law"]'::jsonb,0,'Pressure rises with temperature at fixed volume.','original'),
('127.830.d.2.E',4,'A pneumatic cylinder squeezes air into half its original volume at constant temperature, and the pressure roughly doubles. This follows:','["Gay-Lussac''s Law", "Boyle''s Law", "Charles''s Law", "Newton''s Law"]'::jsonb,1,'Pressure and volume are inversely related.','original'),
('127.830.d.2.F',3,'A pump motor adds energy to the oil, the oil moves the cylinder, and some energy leaves as heat. This shows that energy in a system is:','["created by the pump", "lost completely", "transformed rather than created or destroyed", "destroyed by valves"]'::jsonb,2,'Energy is conserved.','original'),
('127.830.d.2.F',4,'In a fluid power system, why does the oil get warm even though the pump only moves fluid?','["the tank adds energy", "heat is a type of pressure", "oil makes its own heat", "some input energy converts to heat through friction and throttling"]'::jsonb,3,'Losses show up as heat.','original'),
('127.830.d.2.G',3,'Pressure in a hydraulic circuit builds when:','["the pump flow meets resistance from the load", "the oil is removed", "the pump runs with no restriction", "the tank is empty"]'::jsonb,0,'Pumps make flow; resistance creates pressure.','original'),
('127.830.d.2.G',4,'A hydraulic pump running with its outlet open to the tank at idle shows nearly zero pressure because:','["oil has no weight", "there is almost no resistance to flow", "the pump is broken", "gauges never read tank lines"]'::jsonb,1,'No resistance, no pressure.','original'),
('127.830.d.2.H',3,'A rubber seal that hardens and cracks when a system runs far hotter than its rating will most likely:','["change oil color only", "seal better", "leak and allow fluid contamination", "reduce noise"]'::jsonb,2,'Heat degrades seals.','original'),
('127.830.d.2.H',4,'Choosing a seal compound that is compatible with the fluid and operating temperature range matters because the wrong material can:','["remove the need for filters", "improve cooling", "increase pump speed", "swell, harden or break down and fail"]'::jsonb,3,'Match seals to conditions.','original'),
('127.830.d.2.I',3,'The lowest temperature at which an oil gives off enough vapor to briefly flash when a flame passes is its:','["flash point", "boiling point", "fire point", "pour point"]'::jsonb,0,'Flash point is the first brief ignition.','original'),
('127.830.d.2.I',4,'Which statement is correct about fire point and auto-ignition temperature?','["fire point needs no flame", "fire point needs a flame to sustain burning, while auto-ignition occurs with no outside flame", "auto-ignition needs a spark", "they are always identical"]'::jsonb,1,'Auto-ignition is spontaneous.','original'),
('127.830.d.2.J',3,'A pump moves 5 cubic inches of oil each time its shaft turns once. That 5 cubic inches per revolution is the pump''s:','["pour point", "back pressure", "displacement", "viscosity"]'::jsonb,2,'Displacement is volume per revolution.','original'),
('127.830.d.2.J',4,'A pump with a displacement of 2 cubic inches per revolution turns 1,000 rpm. Its ideal flow is about:','["1,002 cubic inches per minute", "500 cubic inches per minute", "20 cubic inches per minute", "2,000 cubic inches per minute"]'::jsonb,3,'2 × 1000 = 2000.','original'),
('127.830.d.2.K',3,'A pinhole leak in a pressurized hydraulic hose sprays a fine stream. The hazard of touching it with a bare hand is:','["high-pressure fluid injection under the skin", "sunburn", "a loose tooth", "a mild rash only"]'::jsonb,0,'Injection injuries are serious.','original'),
('127.830.d.2.K',4,'A technician searches for a hydraulic leak by running a piece of cardboard near the hose instead of her hand because:','["cardboard repairs hoses", "a fine jet can pierce skin and requires emergency treatment", "cardboard makes the leak smaller", "hands are too clean"]'::jsonb,1,'Never use hands to find leaks.','original'),
('127.830.d.3.A',3,'On a schematic, a circle with a triangle pointing outward and a straight line attached is the symbol for a:','["filter", "cylinder", "pump", "check valve"]'::jsonb,2,'Pump symbol has an outward triangle.','original'),
('127.830.d.3.A',4,'A rectangle with a rod symbol on one side and a piston inside most likely represents a:','["reservoir", "accumulator", "motor", "cylinder"]'::jsonb,3,'Cylinders show a piston and rod.','original'),
('127.830.d.3.B',3,'A drawing that uses simple standard symbols to show how components connect, not what they look like, is a:','["schematic diagram", "product photo", "floor plan", "pictorial diagram"]'::jsonb,0,'Schematics use symbols.','original'),
('127.830.d.3.B',4,'A pictorial diagram differs from a schematic because it:','["lists no parts", "shows the actual appearance and placement of components", "never shows hoses", "uses only symbols"]'::jsonb,1,'Pictorials show how parts look.','original'),
('127.830.d.3.C',3,'A technician matches a diamond-shaped schematic box with arrows to a valve body on the bench. She is:','["drawing a pump", "painting a valve", "matching a schematic symbol to a physical component", "ordering oil"]'::jsonb,2,'Symbol-to-part matching.','original'),
('127.830.d.3.C',4,'On the bench, a part with two ports and a ball inside that only passes flow one way matches which schematic symbol?','["a tank symbol", "a cylinder symbol", "a motor symbol", "a check valve symbol"]'::jsonb,3,'One-way flow means check valve.','original'),
('127.830.d.3.D',3,'Following a schematic, a student connects a pump, a directional valve and a cylinder so that shifting the valve extends and retracts the rod. She is:','["constructing and operating a basic circuit", "tuning a chain", "testing a bearing", "cleaning a tank"]'::jsonb,0,'Build the circuit from the schematic.','original'),
('127.830.d.3.D',4,'Before powering a circuit built from a schematic, the student should first:','["bypass the relief valve", "verify connections against the schematic and check that the relief valve is set low", "remove the filter", "run at full pressure"]'::jsonb,1,'Verify and set safe pressure.','original'),
('127.830.d.3.E',3,'A technician looks at a lift gate with a cylinder and writes a drawing using standard symbols for the pump, valve, cylinder and tank. She is:','["editing a payroll form", "painting a gate", "drawing a fluid power schematic from an application", "measuring a weld"]'::jsonb,2,'Draw from the real system.','original'),
('127.830.d.3.E',4,'When drawing a schematic for a simple clamp, the reservoir symbol should connect to the pump inlet and:','["to the clamp jaw only", "to nothing", "to a power outlet", "to the return line of the directional valve"]'::jsonb,3,'Return flow goes to tank.','original'),
('127.830.d.4.A',3,'A gauge at the pump outlet reads normal, but the gauge at the cylinder reads far lower. A likely cause is:','["a leak or restriction between the two gauge points", "a longer hose label", "a full tank", "a gauge painted wrong"]'::jsonb,0,'Pressure drop shows loss.','original'),
('127.830.d.4.A',4,'A cylinder that drifts slowly down under load with no external leak visible most likely has:','["a clean breather", "an internal leak past the piston seal", "a bright gauge", "too much oil in the tank"]'::jsonb,1,'Internal leaks cause drift.','original'),
('127.830.d.4.B',3,'A flow meter reads half of the pump''s rated flow while the cylinder moves very slowly. The meter helps the technician spot:','["a label problem", "a wrong tool color", "improper flow caused by a restriction or worn pump", "a paint problem"]'::jsonb,2,'Flow readings reveal faults.','original'),
('127.830.d.4.B',4,'If a flow meter shows normal flow but the cylinder is still slow under load, the technician should suspect:','["a perfect system", "a bad nameplate", "a high tank level", "internal leakage in the cylinder or valve"]'::jsonb,3,'Normal supply but low output points to bypass.','original'),
('127.830.d.4.C',3,'The temperature gauge on a hydraulic tank climbs steadily to 190 degrees Fahrenheit during a shift. This suggests the system is:','["overheating, perhaps from a stuck relief valve or low oil", "running cold", "overfilled with air", "operating perfectly"]'::jsonb,0,'Heat signals wasted energy.','original'),
('127.830.d.4.C',4,'Oil that stays too hot for long periods will most likely:','["last longer", "thin out, oxidize and shorten seal and fluid life", "cool the pump", "thicken forever"]'::jsonb,1,'Heat damages oil and seals.','original'),
('127.830.d.4.D',3,'A shop uses oil to lift a heavy press and also uses compressed air to blow chips off parts. Which statement correctly compares the two?','["both use gas", "pneumatics use oil only", "hydraulics use liquid that barely compresses; pneumatics use air that compresses", "hydraulics use air only"]'::jsonb,2,'Liquids vs gases.','original'),
('127.830.d.4.D',4,'Why does a pneumatic cylinder feel springy under load compared with a hydraulic cylinder?','["cylinders differ in color", "air is a solid", "oil is lighter", "air compresses, but oil barely does"]'::jsonb,3,'Compressibility difference.','original'),
('127.830.d.4.E',3,'An air dryer is installed after the compressor so that water vapor in the air is removed before it reaches valves. This prevents:','["moisture damage and rust in the pneumatic components", "a loss of paint", "a change in tag shape", "an increase in wire size"]'::jsonb,0,'Dryers protect components.','original'),
('127.830.d.4.E',4,'Water in the lines of an outdoor plant freezes in winter. A dryer helps prevent:','["looser bolts", "frozen lines and blocked air flow", "warmer air", "brighter lights"]'::jsonb,1,'Dry air won''t freeze up.','original'),
('127.830.d.4.F',3,'A small unit adds a fine oil mist to the compressed air before it reaches an air tool. This lubrication reduces:','["tool size", "hose length", "wear and friction on moving parts", "air pressure to zero"]'::jsonb,2,'Lubrication cuts wear.','original'),
('127.830.d.4.F',4,'A pneumatic cylinder starts to stick and squeal. Adding lubricator oil in the air line helps because it:','["adds more air", "heats the line", "removes the cylinder", "reduces friction on seals and rod surfaces"]'::jsonb,3,'Lubricate to cut friction.','original'),
('127.830.d.5.A',3,'A system''s pressure is 1,000 psi and the piston area is 4 square inches. The force the cylinder can push with is:','["4,000 pounds", "1,004 pounds", "996 pounds", "250 pounds"]'::jsonb,0,'F = P × A.','original'),
('127.830.d.5.A',4,'If the same pressure acts on a piston with only 50% of its original area, the output force:','["stays the same", "drops to half", "becomes infinite", "doubles"]'::jsonb,1,'Force depends on area.','original'),
('127.830.d.5.B',3,'A pump supplies 10 gallons per minute to a cylinder. The rod moves faster when the:','["tank is larger", "bore diameter is larger", "bore diameter is smaller for the same flow", "flow is reduced to zero"]'::jsonb,2,'Speed = flow ÷ area.','original'),
('127.830.d.5.B',4,'A cylinder has a 3 square inch piston and receives 231 cubic inches of oil per minute. The rod speed is about:','["3 inches per minute", "693 inches per minute", "231 inches per minute", "77 inches per minute"]'::jsonb,3,'231 ÷ 3 = 77.','original'),
('127.830.d.5.C',3,'If the load on a cylinder increases while flow stays the same, the system pressure:','["rises to push the heavier load", "becomes a vacuum", "stays unrelated", "falls to zero"]'::jsonb,0,'Heavier loads need more pressure.','original'),
('127.830.d.5.C',4,'A cylinder with a 2 square inch piston must push 3,000 pounds. The needed pressure is:','["3,002 psi", "1,500 psi", "6,000 psi", "750 psi"]'::jsonb,1,'3000 ÷ 2 = 1500.','original'),
('127.830.d.5.D',3,'If more oil volume per minute is sent to the same cylinder, the rod moves:','["backward only", "not at all", "faster", "slower"]'::jsonb,2,'More flow, more speed.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_122'
from (values
('127.830.d.5.D',4,'Doubling both the flow rate and the piston area, the rod speed will:','["quadruple", "drop to zero", "double", "stay about the same"]'::jsonb,3,'Speed = flow ÷ area.','original'),
('127.830.d.5.E',3,'A cylinder with a 5 square inch piston is supplied 800 psi. Using Pascal''s Law, the extending force is:','["4,000 pounds", "805 pounds", "160 pounds", "795 pounds"]'::jsonb,0,'800 × 5 = 4000.','original'),
('127.830.d.5.E',4,'To lift a 12,000 pound load with a 6 square inch piston, the pressure needed is:','["72,000 psi", "2,000 psi", "18 psi", "200 psi"]'::jsonb,1,'12000 ÷ 6 = 2000.','original'),
('127.830.d.6.A',3,'A student compares the machine that squeezes atmospheric air into a storage tank with the machine that pushes oil through hoses. The first is a compressor and the second is a:','["relief valve", "gauge", "hydraulic pump", "filter"]'::jsonb,2,'Compressors move air; pumps move oil.','original'),
('127.830.d.6.A',4,'Which difference is correct?','["both move solids", "a pump moves only air", "a compressor moves oil", "a compressor raises the pressure of a gas; a hydraulic pump moves a nearly incompressible liquid"]'::jsonb,3,'Gas versus liquid.','original'),
('127.830.d.6.B',3,'Oil returning from the circuit sits in the tank, where heat dissipates and air bubbles and dirt settle out. These are functions of the hydraulic:','["reservoir", "accumulator", "actuator", "strainer"]'::jsonb,0,'Reservoirs store, cool and settle fluid.','original'),
('127.830.d.6.B',4,'A reservoir baffle plate separates the return line from the pump suction so that:','["oil never cools", "bubbles and contaminants can settle before oil is pumped again", "air enters the pump", "oil never moves"]'::jsonb,1,'Baffles improve settling.','original'),
('127.830.d.6.C',3,'A pump with two meshing toothed wheels that carry oil around the housing is a:','["diaphragm pump", "vane pump", "gear pump", "piston pump"]'::jsonb,2,'Gear pumps use meshing gears.','original'),
('127.830.d.6.C',4,'A pump with sliding blades in a slotted rotor that spins inside an offset ring is a:','["piston pump", "gear pump", "fan", "vane pump"]'::jsonb,3,'Vane pumps use sliding vanes.','original'),
('127.830.d.6.D',3,'A pump that moves the same volume every revolution unless the speed changes is a:','["fixed displacement pump", "variable displacement pump", "bladder pump", "vacuum pump"]'::jsonb,0,'Fixed means constant volume per turn.','original'),
('127.830.d.6.D',4,'A pump whose swash plate angle can be changed to vary flow at constant speed is a:','["manual jack", "variable displacement pump", "fixed displacement gear pump", "hand pump"]'::jsonb,1,'Variable displacement changes output.','original'),
('127.830.d.6.E',3,'The device that turns hydraulic power into useful work such as pushing, pulling or turning is the:','["strainer", "gauge", "actuator", "tank"]'::jsonb,2,'Actuators do the work.','original'),
('127.830.d.6.E',4,'If the actuator is removed from a circuit, the oil would have:','["more work to do", "no pressure at all times", "a larger pump", "no way to produce useful motion or force"]'::jsonb,3,'Without actuators there is no output.','original'),
('127.830.d.6.F',3,'A technician mounts a dial that reads system pressure and a meter that reads oil flow rate. Together they help:','["monitor how the system is performing", "slow the pump", "hide leaks", "decorate the circuit"]'::jsonb,0,'Gauges and meters monitor.','original'),
('127.830.d.6.F',4,'A pressure gauge on a hydraulic power unit lets an operator confirm that the:','["hoses are new", "system is operating at the correct pressure", "oil is blue", "tank is painted"]'::jsonb,1,'Pressure gauges show operating pressure.','original'),
('127.830.d.6.G',3,'A hydraulic valve that sets the highest allowed pressure and dumps extra flow back to the tank is a:','["check valve", "flow meter", "relief valve", "sight glass"]'::jsonb,2,'Relief valves cap pressure.','original'),
('127.830.d.6.G',4,'A valve that lowers pressure in one branch of a circuit below the main system pressure is a:','["check valve", "filter", "relief valve at tank", "pressure reducing valve"]'::jsonb,3,'Reducing valves lower branch pressure.','original'),
('127.830.d.6.H',3,'On a compressed air line, a device that holds downstream pressure at a steady lower value is a:','["regulator", "compressor", "dryer", "filter"]'::jsonb,0,'Regulators set downstream pressure.','original'),
('127.830.d.6.H',4,'A small valve on an air receiver that opens to vent air if tank pressure goes too high is a:','["muffler", "safety relief valve", "needle valve", "regulator gauge"]'::jsonb,1,'Safety valves protect tanks.','original'),
('127.830.d.6.I',3,'A needle valve in a hydraulic line is turned in to slow a cylinder''s travel. This valve is a:','["pressure gauge", "shut-off tank", "flow control valve", "pump"]'::jsonb,2,'Flow controls set speed.','original'),
('127.830.d.6.I',4,'Closing down a flow control valve in series with a cylinder will:','["increase speed", "remove pressure", "raise voltage", "reduce the actuator speed"]'::jsonb,3,'Less flow means slower speed.','original'),
('127.830.d.6.J',3,'A hydraulic motor that turns only one direction when oil flows through it in one way is a:','["unidirectional motor", "linear cylinder", "bidirectional motor", "accumulator"]'::jsonb,0,'Single-direction rotation.','original'),
('127.830.d.6.J',4,'A motor that can turn clockwise or counterclockwise depending on which port gets oil is a:','["unidirectional motor", "bidirectional motor", "check valve", "gauge"]'::jsonb,1,'Reversible rotation.','original'),
('127.830.d.6.K',3,'Compressed air pushes on a piston to lift a part on an assembly line, and a hydraulic motor turns a conveyor. Both devices are:','["filters", "dryers", "actuators", "reservoirs"]'::jsonb,2,'Actuators produce motion.','original'),
('127.830.d.6.K',4,'Which pair of actuators produces linear and rotary motion, in that order?','["a filter and a gauge", "a strainer and a pump", "a motor and a cylinder", "a cylinder and a motor"]'::jsonb,3,'Cylinder linear, motor rotary.','original'),
('127.830.d.6.L',3,'A cylinder that uses fluid to push the rod out and a spring to bring it back is a:','["single-acting cylinder", "pump", "rotary motor", "double-acting cylinder"]'::jsonb,0,'Single-acting uses spring return.','original'),
('127.830.d.6.L',4,'A telescoping cylinder is chosen when a:','["short stroke only", "long stroke is needed from a short retracted length", "no rod", "zero pressure"]'::jsonb,1,'Telescoping cylinders extend in stages.','original'),
('127.830.d.6.M',3,'A cylinder with ports at both ends so that fluid pushes the piston out and also brings it back is:','["spring-return", "single-acting", "double-acting", "gravity-return"]'::jsonb,2,'Both directions are powered.','original'),
('127.830.d.6.M',4,'On the retract stroke of a double-acting cylinder, the oil is fed to the:','["gauge port", "cap end", "tank only", "rod end"]'::jsonb,3,'Retraction uses the rod-end port.','original'),
('127.830.d.6.N',3,'A flow control valve in a circuit lets an operator slow a cylinder to a crawl so that a part can be pressed gently. This shows the valve:','["regulates actuator speed", "raises pressure", "stores energy", "filters oil"]'::jsonb,0,'Flow valves control speed.','original'),
('127.830.d.6.N',4,'A meter-out flow control placed on the cylinder''s outlet helps prevent:','["pressure from rising", "a load from running away", "tanks from filling", "filters from clogging"]'::jsonb,1,'Meter-out gives control against overrunning loads.','original'),
('127.830.d.6.O',3,'A part that lets oil pass freely in one direction but blocks reverse flow, holding a load in place when the pump stops, is a:','["gauge", "flow meter", "check valve", "relief valve"]'::jsonb,2,'Check valves hold load.','original'),
('127.830.d.6.O',4,'A pilot-operated check valve is used to:','["change the oil color", "filter oil", "keep oil hot", "hold a cylinder in position until pilot pressure lets it release"]'::jsonb,3,'Pilot checks release on demand.','original'),
('127.830.d.6.P',3,'A hydraulic accumulator stores pressurized fluid and releases it when needed, which can:','["smooth out pressure spikes and supply extra flow", "stop all oil", "lower gauge numbers only", "raise noise"]'::jsonb,0,'Accumulators store energy.','original'),
('127.830.d.6.P',4,'If the pump shuts off, an accumulator on the circuit can:','["add pressure instantly forever", "still supply fluid briefly to finish a cycle", "damage the tank", "remove oil"]'::jsonb,1,'Stored fluid provides emergency power.','original'),
('127.830.d.7.A',3,'A designer sketches a circuit in which a pump feeds a fixed-direction motor through a flow control valve, with a return line to the tank. This is a design for a:','["lighting circuit", "vacuum circuit", "circuit with a unidirectional motor", "circuit with two cylinders only"]'::jsonb,2,'Unidirectional motor circuit.','original'),
('127.830.d.7.A',4,'In a design with a unidirectional motor, the motor outlet line should connect to the:','["tool tray", "relief valve cap", "pump inlet gauge", "reservoir"]'::jsonb,3,'Return flow goes to tank.','original'),
('127.830.d.7.B',3,'A designer wants a conveyor motor to spin both ways. The directional valve should have positions that send oil to either motor port, which makes it a:','["circuit with a bi-directional motor", "unidirectional circuit", "manual lift", "pneumatic dryer"]'::jsonb,0,'Reversing motor circuit.','original'),
('127.830.d.7.B',4,'To stop a bi-directional motor from free-spinning when the valve is centered, the designer can pick a center position that:','["opens both ports to tank", "blocks both motor ports", "drains the tank", "removes the pump"]'::jsonb,1,'Blocked center holds motor.','original'),
('127.830.d.7.C',3,'A designer plans a circuit where one pump powers a lift cylinder and a clamp cylinder using two directional valves. This is a circuit with:','["no actuators", "a vacuum generator", "multiple cylinders", "a single motor"]'::jsonb,2,'Two actuators on one pump.','original'),
('127.830.d.7.C',4,'When two cylinders are plumbed in parallel to one pump, the cylinder with the lighter load will usually move:','["last", "backward", "never", "first"]'::jsonb,3,'Oil takes the path of least resistance.','original'),
('127.830.d.7.D',3,'The designer adds an adjustable valve in the line to a cylinder so that the rod can be slowed during a delicate press. This is a circuit with a:','["flow control valve", "bigger motor", "new tank", "pressure gauge only"]'::jsonb,0,'Flow control sets speed.','original'),
('127.830.d.7.D',4,'A designer who wants the rod to extend slowly but retract quickly can place a flow control valve with a built-in check so that:','["pressure disappears", "free flow goes one way and metered flow goes the other", "flow only goes backward", "no flow goes either way"]'::jsonb,1,'Check bypasses the meter.','original'),
('127.830.d.7.E',3,'A designer adds a part that blocks reverse flow so a lifted load does not sink when the pump stops. This design incorporates a:','["tank breather", "relief valve alone", "check valve", "flow meter"]'::jsonb,2,'Check valve holds load.','original'),
('127.830.d.7.E',4,'In a circuit with a check valve, the arrow on its schematic symbol points toward the direction of:','["the filter", "blocked flow", "the pump''s motor", "free flow"]'::jsonb,3,'Arrow shows free flow direction.','original'),
('127.830.d.7.F',3,'A designer uses a four-way, three-position directional valve to extend, hold and retract a cylinder. This shows:','["a basic circuit using a directional control valve configuration", "a gauge test", "a vacuum generator", "a filter change"]'::jsonb,0,'4/3 valves give three positions.','original'),
('127.830.d.7.F',4,'A 4-way valve gets its name because it has:','["four gauges", "four working ports", "four motors", "four tanks"]'::jsonb,1,'Ports P, T, A, B.','original'),
('127.830.d.7.G',3,'A designer chooses a lever, a push button and an electric solenoid as the ways to shift directional valves. These are:','["kinds of fluids", "kinds of tanks", "operators for directional control", "kinds of filters"]'::jsonb,2,'Operators shift valves.','original'),
('127.830.d.7.G',4,'Which operator would let a computer shift a valve without a person touching it?','["a hand lever", "a foot pedal", "a spring", "a solenoid"]'::jsonb,3,'Solenoids are electric operators.','original'),
('127.830.d.7.H',3,'A designer wants a clamp cylinder to hold a part before a drill cylinder moves. A sequence valve opens only after the first cylinder reaches a set pressure, so it:','["operates multiple actuators in order", "stops all actuators", "lowers tank level", "raises noise only"]'::jsonb,0,'Sequence valves order motion.','original'),
('127.830.d.7.H',4,'If the clamp cylinder in a sequence circuit does not reach the sequence valve''s set pressure, the second cylinder will:','["move backward", "not move", "explode", "move first"]'::jsonb,1,'The valve stays closed below set pressure.','original'),
('127.830.d.7.I',3,'A designer needs a branch that feeds a small clamp at 500 psi from a 2,000 psi main line. The device is a:','["accumulator", "sequence valve", "pressure reducing valve", "tank strainer"]'::jsonb,2,'Reducing valves cut branch pressure.','original'),
('127.830.d.7.I',4,'The branch circuit downstream of a reducing valve sees pressure that is:','["zero in all cases", "higher than the main", "always at main pressure", "at or below the valve''s set value"]'::jsonb,3,'Downstream is limited.','original'),
('127.830.d.8.A',3,'A technician joins hydraulic lines using threaded fittings, flared tube fittings and quick-disconnect couplers. These are:','["methods of connecting fluid power circuits", "methods for painting hoses", "methods for storing oil", "methods for cooling tanks"]'::jsonb,0,'Common connection methods.','original'),
('127.830.d.8.A',4,'Wrapping the male threads of a tapered pipe fitting with the right sealant tape helps to:','["reduce flow", "prevent leaks at the joint", "raise noise", "warm the oil"]'::jsonb,1,'Sealant fills thread gaps.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_122'
from (values
('127.830.d.8.B',3,'Before cutting into a pressurized hydraulic line for a new installation, a technician must first:','["remove the gauge", "spray the fitting", "lock out the power and relieve all pressure", "open the line live"]'::jsonb,2,'De-energize and depressurize.','original'),
('127.830.d.8.B',4,'During installation, wearing safety glasses and gloves and keeping hands away from pinholes helps protect against:','["paint chips only", "static noise", "color fading", "fluid injection and splashes"]'::jsonb,3,'PPE protects from fluid hazards.','original'),
('127.830.d.8.C',3,'After building the plan for a drive circuit, a technician mounts the pump, the directional valve and a fixed-direction motor and plumbs them with hoses. She is installing a:','["circuit with a unidirectional motor", "vacuum circuit", "paint circuit", "lighting circuit"]'::jsonb,0,'Install per design.','original'),
('127.830.d.8.C',4,'After installing the motor circuit, the first thing to verify before full speed is:','["color of hoses", "correct rotation and no leaks at low pressure", "tank paint", "full-pressure operation immediately"]'::jsonb,1,'Check at low pressure first.','original'),
('127.830.d.8.D',3,'A technician installs a reversible hydraulic motor with a directional valve and connects the valve''s two work ports to each motor port. She is installing a:','["vacuum circuit", "manual jack", "circuit with a bi-directional motor", "unidirectional circuit"]'::jsonb,2,'Two work ports to two motor ports.','original'),
('127.830.d.8.D',4,'After wiring a bi-directional motor circuit, shifting the valve one way should turn the motor one direction and the other way should:','["vent the tank", "do nothing", "stop the pump", "turn it the opposite direction"]'::jsonb,3,'Reversing check.','original'),
('127.830.d.8.E',3,'A technician pipes two cylinders to the same pump through two directional valves. She is installing a circuit with:','["multiple cylinders", "no actuators", "a single motor", "a vacuum generator"]'::jsonb,0,'Two actuators installed.','original'),
('127.830.d.8.E',4,'When bleeding air from a newly installed cylinder, the technician should:','["run it at full speed dry", "cycle the cylinder slowly several times at low pressure", "close all ports", "remove the rod"]'::jsonb,1,'Slow cycling purges air.','original'),
('127.830.d.8.F',3,'A technician installs a needle valve in the line to slow a cylinder to a crawl. This is a circuit with a:','["pressure gauge only", "new reservoir", "flow control valve", "vacuum pad"]'::jsonb,2,'Flow valve installed.','original'),
('127.830.d.8.F',4,'To verify that the installed flow control valve works, the technician adjusts it and observes the rod:','["never move", "move backward", "stay at one speed", "change speed as the setting is changed"]'::jsonb,3,'Speed responds to adjustment.','original'),
('127.830.d.8.G',3,'A technician installs a one-way valve in a lift circuit so that the load will not drop when the pump shuts off. This is installing:','["a check valve", "a muffler", "a vacuum pump", "a heat exchanger"]'::jsonb,0,'Check valve installed.','original'),
('127.830.d.8.G',4,'When mounting a check valve, the flow arrow on the body must point:','["at the floor", "in the direction of free flow", "against free flow", "at the tank wall"]'::jsonb,1,'Orientation matters.','original'),
('127.830.d.8.H',3,'A technician fits a directional control valve with a mounting plate, O-rings and bolts and connects the A and B ports to a cylinder. She is installing:','["a fuel line", "a vacuum circuit", "a basic circuit using a directional control valve", "a wiring harness"]'::jsonb,2,'Installing a basic DCV circuit.','original'),
('127.830.d.8.H',4,'When bolting a subplate-mounted valve to the manifold, the technician makes sure:','["the bolts are loose", "the ports are blocked", "the O-rings are left out", "the O-rings are seated and the bolts are torqued evenly"]'::jsonb,3,'Proper seating prevents leaks.','original'),
('127.830.d.8.I',3,'A technician installs a hand lever on one valve, a push button on another and a solenoid on a third. She is installing:','["operators for directional control", "filters for oil", "meters for flow", "gauges for pressure"]'::jsonb,0,'Operators shift valves.','original'),
('127.830.d.8.I',4,'After installing a solenoid operator, the technician must also:','["spray it with water", "connect it to the correct voltage supply safely", "leave it unwired", "remove the coil"]'::jsonb,1,'Match voltage.','original'),
('127.830.d.8.J',3,'A technician turns the knob on an air regulator until the downstream gauge shows 90 psi to match the system requirement. She is:','["draining a tank", "painting a hose", "adjusting a pneumatic regulator to a defined system pressure", "changing a bearing"]'::jsonb,2,'Adjust to specified pressure.','original'),
('127.830.d.8.J',4,'To set a regulator accurately, the technician should turn the adjusting knob while watching the:','["supply tag", "tank paint", "pump housing", "downstream gauge"]'::jsonb,3,'Downstream gauge shows set pressure.','original'),
('127.830.d.8.K',3,'With the system running, a technician adjusts the power unit''s relief valve to open at 1,500 psi as the specification requires. She is:','["adjusting a hydraulic relief valve to a defined system pressure", "changing a hose", "testing a filter", "filling a tank"]'::jsonb,0,'Adjust relief to spec.','original'),
('127.830.d.8.K',4,'The safe way to adjust a relief valve is to:','["run it with the pump off", "dead-head the system with a gauge installed and turn the screw slowly", "remove the gauge", "use the highest setting first"]'::jsonb,1,'Slowly adjust and watch the gauge.','original'),
('127.830.d.8.L',3,'A technician plumbs a sequence valve between two cylinders so that the second begins moving after the first completes its stroke. She is:','["removing a reservoir", "draining oil", "installing a sequence valve to operate actuators in order", "testing a seal"]'::jsonb,2,'Sequence valve install.','original'),
('127.830.d.8.L',4,'After installing a sequence valve, the technician sets its pressure slightly above:','["the ambient temperature", "the tank vacuum", "zero", "the pressure needed to complete the first cylinder''s motion"]'::jsonb,3,'Set above first-stage pressure.','original'),
('127.830.d.8.M',3,'A technician fits a pressure reducing valve on a branch line so a small clamp sees less pressure than the main circuit. She is:','["installing a pressure reducing valve in a branch circuit", "installing a tank", "installing a pump", "installing a dryer"]'::jsonb,0,'Reducing valve install.','original'),
('127.830.d.8.M',4,'After installation, the technician confirms the reducing valve by checking that the branch gauge reads:','["zero always", "the lower set pressure while the main gauge reads higher", "a negative value", "the same as the main"]'::jsonb,1,'Branch below main.','original'),
('127.830.d.9.A',3,'A maintenance planner reviews service records showing that filters on a hydraulic press clog every 600 hours. She sets a filter change at 500 hours. This is developing a:','["payroll plan", "parking plan", "preventive maintenance schedule from service data", "sales forecast"]'::jsonb,2,'Use history to schedule PM.','original'),
('127.830.d.9.A',4,'A preventive maintenance schedule differs from fixing parts only after failure because it:','["waits for breakdowns", "avoids records", "skips inspection", "performs service at planned intervals before breakdowns"]'::jsonb,3,'PM is proactive.','original'),
('127.830.d.9.B',3,'Repair logs show that a pump motor bearing fails after roughly 9,000 hours, so a technician plans to replace it at 8,000. This is using repair data for:','["predictive maintenance", "tool storage", "price checks", "reactive repair only"]'::jsonb,0,'Predict failures from data.','original'),
('127.830.d.9.B',4,'Which data best supports a predictive maintenance decision on a hydraulic pump?','["warehouse size", "trends in vibration, temperature and past failure hours", "paint color", "operator''s lunch time"]'::jsonb,1,'Condition data predicts failure.','original'),
('127.830.d.9.C',3,'During a walk-around, a technician spots a weeping fitting, a swollen hose and a dented cylinder rod. She is inspecting components for:','["pay stubs", "marketing ideas", "signs of malfunction such as leaks, wear and damage", "label colors"]'::jsonb,2,'Look for failure signs.','original'),
('127.830.d.9.C',4,'A cylinder rod with scratches that catch a fingernail should be flagged because it can:','["cool the oil", "improve sealing", "reduce friction", "cut the rod seal and cause leaks"]'::jsonb,3,'Scored rods damage seals.','original'),
('127.830.d.9.D',3,'A technician draws a sample of oil that looks milky. This suggests the fluid is contaminated with:','["water", "paint", "extra additives", "fresh oil"]'::jsonb,0,'Milky oil signals water or air.','original'),
('127.830.d.9.D',4,'Oil that smells burnt and looks dark and thin is a sign of:','["a new filter", "viscosity breakdown from overheating", "fresh fluid", "a clean tank"]'::jsonb,1,'Heat degrades oil.','original'),
('127.830.d.9.E',3,'After shutting down and relieving pressure, a technician unscrews the old filter, wipes the mount, lightly oils the new gasket and spins the new filter on by hand. She is:','["testing a gauge", "draining a tank", "changing a filter in a fluid power system", "bleeding a cylinder"]'::jsonb,2,'Filter change steps.','original'),
('127.830.d.9.E',4,'Before removing a pressure filter, the technician must:','["skip the lockout", "run the pump hot", "open the relief valve in operation", "lock out and relieve system pressure"]'::jsonb,3,'Depressurize first.','original'),
('127.830.d.9.F',3,'A technician pumps the old oil from the reservoir into a drum, wipes out the sludge, refills with the specified fluid and cycles the system. She is:','["draining and replacing hydraulic fluid", "painting the tank", "changing a belt", "testing a regulator"]'::jsonb,0,'Fluid change steps.','original'),
('127.830.d.9.F',4,'Used hydraulic fluid should be:','["poured on the ground", "collected and disposed of through approved recycling", "poured in a drain", "burned in the lot"]'::jsonb,1,'Dispose properly.','original'),
('127.830.d.10.A',3,'A compressed air line runs through a narrowed throat so that air speeds up and creates a low-pressure zone that pulls on a suction cup. This describes a:','["diaphragm", "gear pump", "venturi vacuum application", "hydraulic accumulator"]'::jsonb,2,'Venturi uses speed to create vacuum.','original'),
('127.830.d.10.A',4,'The Bernoulli effect used in a venturi means that when air speed in the throat rises, the pressure there:','["stays equal", "rises", "doubles", "drops"]'::jsonb,3,'Faster flow, lower pressure.','original'),
('127.830.d.10.B',3,'A technician attaches a gauge to a vacuum port and reads 20 inches of mercury. This gauge shows:','["how far below atmospheric pressure the system is", "the oil temperature", "the tank level", "the motor speed"]'::jsonb,0,'Vacuum gauges read below atmospheric.','original'),
('127.830.d.10.B',4,'A higher inches-of-mercury reading on a vacuum gauge means:','["no vacuum", "a stronger vacuum", "a weaker vacuum", "higher air pressure"]'::jsonb,1,'Greater vacuum, larger number.','original'),
('127.830.d.10.C',3,'A technician connects a U-shaped tube partly filled with liquid to measure small pressure differences. This device is a:','["torque wrench", "tachometer", "manometer", "dial caliper"]'::jsonb,2,'Manometers measure pressure by liquid height.','original'),
('127.830.d.10.C',4,'If the liquid column in a manometer is higher on one side by 6 inches, the pressure difference is read as:','["6 pounds", "6 revolutions", "6 volts", "6 inches of that liquid"]'::jsonb,3,'Height difference gives the pressure.','original'),
('127.830.d.10.D',3,'A technician plumbs shop air to a small unit and turns on the supply until a suction cup holds a plate. She is:','["connecting and operating a vacuum generator", "changing a filter", "charging an accumulator", "bleeding a cylinder"]'::jsonb,0,'Vacuum generator operation.','original'),
('127.830.d.10.D',4,'If the suction cup will not hold a plate, a first check on the vacuum generator should be:','["tank paint", "supply air pressure and leaks at the cup", "gauge color", "tool brand"]'::jsonb,1,'Inspect supply and seal.','original'),
('127.830.d.10.E',3,'A vacuum generator has no moving parts and creates vacuum by sending compressed air through an ejector nozzle. Its function is to:','["pump fluid", "store oil", "produce a vacuum from compressed air", "filter water"]'::jsonb,2,'Ejectors create vacuum.','original'),
('127.830.d.10.E',4,'A benefit of an air-driven vacuum generator over an electric vacuum pump is that it:','["uses no air", "needs a motor", "needs oil changes", "has no moving parts and responds quickly"]'::jsonb,3,'Simple and fast.','original'),
('127.830.d.10.F',3,'A technician tees a venturi into an air line so that air flowing through it will pull a vacuum at a side port. She is:','["connecting a venturi to a pneumatic system", "adjusting a relief valve", "draining a tank", "painting a manifold"]'::jsonb,0,'Venturi hookup.','original'),
('127.830.d.10.F',4,'For a venturi to work properly, the air supply should be:','["absent", "clean, dry and at the pressure the unit is rated for", "wet and dirty", "unregulated and varied"]'::jsonb,1,'Quality supply needed.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
